  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker1');
  await h.deliverAll();
  await h.cancel();
  assert.deepEqual((await h.inFlight()).map((m) => m.to), ['worker0']);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'cancelled', task1: 'completed' });
});

