import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

test('happy path', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', retried0: false, retried1: false, processed: PROC });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0', 1), { ok: true });
  const r = await h.inFlight();
  assert.deepEqual(r.map((m) => [m.from, m.to, m.action, m.data]), [['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', retried0: false, retried1: false, processed: PROC });
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false, processed: PROC });
  assert.equal((await h.workDone('nobody', 1)).ok, false);
});

test('cancel with a report in flight', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  assert.equal((await h.inFlight()).filter((m) => m.action === 'Abort').length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', retried0: false, retried1: false, processed: PROC });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('a failed task is retried once', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: true, retried1: false, processed: PROC });
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workDone('worker1', 1);
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: true, retried1: false, processed: PROC });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
});

test('a retry that then completes', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  await h.workDone('worker1', 1);
  await h.workDone('worker0', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: true, processed: PROC });
});

test('a timeout fails the task and aborts its worker', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start();
  await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual((await h.inFlight()).map((m) => [m.to, m.action]), [['worker0', 'Abort']]);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: false, retried1: false, processed: PROC });
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: false, retried1: false, processed: PROC });
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: false, retried1: false, processed: PROC });
});

test('a late report after a timeout is ignored', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker1', 1);
  await h.taskTimeout(1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'failed', retried0: false, retried1: false, processed: PROC });
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'cancelled', task1: 'failed', retried0: false, retried1: false, processed: PROC });
});

test('cancel completes as cancelled', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker1', 1);
  await h.deliverAll();
  await h.cancel();
  assert.deepEqual((await h.inFlight()).map((m) => m.to), ['worker0']);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'cancelled', task1: 'completed', retried0: false, retried1: false, processed: PROC });
});

